"""Small robust client for the local order service (stdlib only)."""
import http.client
import json
import time
import urllib.error
import urllib.request
from collections import Counter

BASE = "http://localhost:8080"


class Client:
    def __init__(self, log_path, pace=0.1):
        self.token = None
        self.log = open(log_path, "a")
        self.stats = Counter()
        self.pace = pace

    def _log(self, msg):
        line = f"{time.strftime('%H:%M:%S')} {msg}"
        self.log.write(line + "\n")
        self.log.flush()

    def _raw(self, method, path, auth):
        headers = {}
        if auth:
            headers["Authorization"] = f"Bearer {self.token}"
        req = urllib.request.Request(BASE + path, method=method, headers=headers)
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                return resp.status, resp.read(), resp.headers
        except urllib.error.HTTPError as e:
            return e.code, e.read(), e.headers

    @staticmethod
    def _retry_after(headers, data):
        waits = []
        h = headers.get("Retry-After") if headers is not None else None
        if h is not None:
            try:
                waits.append(float(h))
            except ValueError:
                pass
        if isinstance(data, dict):
            v = data.get("retry_after")
            if isinstance(v, (int, float)):
                waits.append(float(v))
        return max(waits) if waits else None

    def request(self, method, path, auth=True, ok_statuses=(200,), max_attempts=60):
        """Return (status, parsed_json) for a status in ok_statuses; retry everything else."""
        backoff = 1.0
        for attempt in range(1, max_attempts + 1):
            if auth and self.token is None:
                self.refresh_token()
            if self.pace:
                time.sleep(self.pace)
            try:
                status, body, headers = self._raw(method, path, auth)
            except (urllib.error.URLError, ConnectionError, TimeoutError,
                    http.client.HTTPException, OSError) as e:
                self.stats["network_error"] += 1
                self._log(f"{method} {path} attempt={attempt} NETWORK {e!r}; sleep {backoff}")
                time.sleep(backoff)
                backoff = min(backoff * 2, 30)
                continue
            self.stats[f"http_{status}"] += 1
            try:
                data = json.loads(body)
            except ValueError:
                self.stats["bad_json"] += 1
                self._log(f"{method} {path} attempt={attempt} status={status} BAD JSON {body[:200]!r}; sleep {backoff}")
                time.sleep(backoff)
                backoff = min(backoff * 2, 30)
                continue
            if status in ok_statuses:
                if status != 200:
                    self._log(f"{method} {path} attempt={attempt} status={status} body={str(data)[:200]}")
                return status, data
            wait = self._retry_after(headers, data)
            if status == 429:
                wait = wait if wait is not None else 1.0
                self._log(f"{method} {path} attempt={attempt} 429 body={data} hdr_retry_after={headers.get('Retry-After')}; sleep {wait}")
                time.sleep(wait)
                continue
            if status in (401, 403):
                self._log(f"{method} {path} attempt={attempt} status={status} body={data}; refreshing token (was {self.token})")
                self.token = None
                if wait:
                    time.sleep(wait)
                continue
            # 5xx or anything unexpected: back off and repeat
            sleep_for = wait if wait is not None else backoff
            self._log(f"{method} {path} attempt={attempt} status={status} body={str(data)[:200]} hdr={dict(headers)}; sleep {sleep_for}")
            time.sleep(sleep_for)
            backoff = min(backoff * 2, 30)
        raise RuntimeError(f"giving up on {method} {path} after {max_attempts} attempts")

    def refresh_token(self):
        _, data = self.request("POST", "/token", auth=False)
        tok = data.get("token") if isinstance(data, dict) else None
        if not isinstance(tok, str) or not tok:
            raise RuntimeError(f"bad token response {data!r}")
        self.stats["tokens_issued"] += 1
        self._log(f"new token {tok}")
        self.token = tok

